# Read existing stories
with open('src/data/stories.json', 'r', encoding='utf-8') as f:
    existing_stories = json.load(f)

print(f"Existing stories count: {len(existing_stories)}")

# Filter out duplicates if script is run multiple times
existing_ids = {s['id'] for s in existing_stories}
added_count = 0

for new_s in NEW_STORIES:
    if new_s['id'] in existing_ids:
        # Update existing
        for i, s in enumerate(existing_stories):
            if s['id'] == new_s['id']:
                existing_stories[i] = new_s
                break
    else:
        existing_stories.append(new_s)
        added_count += 1

# Write back
with open('src/data/stories.json', 'w', encoding='utf-8') as f:
    json.dump(existing_stories, f, ensure_ascii=False, indent=2)

print(f"Successfully appended {added_count} new stories. Total stories now: {len(existing_stories)}")
